    'fix.consent.external_service': ["Entiendo que los navegadores consultarán un servidor STUN público (Google) y este verá sus direcciones IP.", "I understand browsers will query a public STUN server (Google) and it will see their IP addresses.", "Entendo que os navegadores consultarão um servidor STUN público (Google) e ele verá seus endereços IP."],
    'calls.confirm': ["Entiendo que hay {n} llamada(s) activa(s) y puede afectarlas.", "I understand there are {n} active call(s) and this may affect them.", "Entendo que há {n} chamada(s) ativa(s) e isso pode afetá-las."],
    'fix.le.d': ["Abriremos el módulo de certificados de Issabel con {host}. Cuando termines, vuelve aquí y comprueba.", "We will open the Issabel certificate module with {host}. When you finish, come back here and check.", "Abriremos o módulo de certificados do Issabel com {host}. Quando terminar, volte aqui e verifique."],
    'fix.le.open': ["Abrir Let's Encrypt", "Open Let's Encrypt", "Abrir Let's Encrypt"],
    'fix.recheck.done': ["Ya lo hice, volver a comprobar", "I did it, check again", "Já fiz, verificar de novo"],
    'fix.ext.d': ["Se abre la edición del anexo {ext} en IssabelPBX. Revisa que use el transporte seguro (wss) y guarda.", "The edit page for extension {ext} opens in IssabelPBX. Check that it uses the secure transport (wss) and save.", "Abre a edição do ramal {ext} no IssabelPBX. Confira que usa o transporte seguro (wss) e salve."],
    'fix.cmd.d': ["Copia este comando y ejecútalo como root en la central. Debajo tienes el comando para revertirlo.", "Copy this command and run it as root on the PBX. Below is the command to revert it.", "Copie este comando e execute-o como root na central. Abaixo está o comando para revertê-lo."],
    'fix.cmd.label': ["Comando (como root)", "Command (as root)", "Comando (como root)"],
    'fix.undo.label': ["Para revertirlo", "To revert it", "Para reverter"],
    'fix.needs.certbot': ["Necesita certbot 5.4 o superior. El de esta central puede ser más antiguo: revisa su versión antes.", "It needs certbot 5.4 or newer. The one on this PBX may be older: check its version first.", "Precisa do certbot 5.4 ou superior. O desta central pode ser mais antigo: confira a versão antes."],
    'fix.needs.helper': ["Primero instala el ayudante de administración con el instalador de la unidad.", "First install the admin helper with the unit installer.", "Primeiro instale o ajudante de administração com o instalador da unidade."],
    'fix.needs.proxy': ["Revisa que Apache tenga cargado proxy_wstunnel y una ruta hacia Asterisk.", "Check that Apache has proxy_wstunnel loaded and a route to Asterisk.", "Confira se o Apache tem proxy_wstunnel carregado e uma rota para o Asterisk."],
    'fix.link.d.pjsip': ["Revisa la configuración PJSIP en IssabelPBX: el transporte wss debe existir.", "Review the PJSIP settings in IssabelPBX: the wss transport must exist.", "Revise a configuração PJSIP no IssabelPBX: o transporte wss deve existir."],
